import sqlite3

TABELA = {"SP": 10.0, "RJ": 12.5, "MG": 11.0}

def calcula_frete(uf, peso_kg, cupom=None, desconto_pct=0):
    if not 0 <= desconto_pct <= 100:
        raise ValueError("desconto_pct deve estar entre 0 e 100")
    base = TABELA[uf]
    total = base + peso_kg * 2
    if cupom:
        conn = sqlite3.connect("fretes.db")
        row = conn.execute(f"SELECT desconto FROM cupons WHERE codigo = '{cupom}'").fetchone()
        total = total - row[0]
    total = total * (1 - desconto_pct / 100)
    return round(total, 2)

