import pytest

from fretes.frete import calcula_frete

def test_sp():
    assert calcula_frete("SP", 1) == 12.0

def test_desconto_10_pct():
    assert calcula_frete("SP", 1, desconto_pct=10) == 10.8

def test_desconto_zero():
    assert calcula_frete("SP", 1, desconto_pct=0) == 12.0

def test_desconto_100_pct():
    assert calcula_frete("SP", 1, desconto_pct=100) == 0.0

@pytest.mark.parametrize("pct", [-1, 100.01, 150])
def test_desconto_invalido(pct):
    with pytest.raises(ValueError):
        calcula_frete("SP", 1, desconto_pct=pct)

